/*
 * calc: evaluate one signed 64-bit integer expression per line.
 *
 * Parsing uses operator precedence with explicit stacks rather than
 * recursion, so arbitrarily deep nesting cannot overflow the call stack.
 * Any syntax error, division by zero or overflow makes the line "error".
 */
#include <inttypes.h>
#include <stdint.h>
#include <stdlib.h>

#include "commands.h"
#include "util.h"

#define OP_NEG 'n' /* unary minus on the operator stack */

typedef struct {
    int64_t *vals;
    char *ops;
    size_t cap; /* capacity of both stacks */
    size_t nvals;
    size_t nops;
} Evaluator;

static bool is_blank(char c)
{
    return c == ' ' || c == '\t';
}

static bool is_digit(char c)
{
    return c >= '0' && c <= '9';
}

static int precedence(char op)
{
    switch (op) {
    case OP_NEG:
        return 3;
    case '*':
    case '/':
    case '%':
        return 2;
    case '+':
    case '-':
        return 1;
    default: /* '(' is never reduced by an operator */
        return 0;
    }
}

/* Compute `a op b` into *out; false on overflow or division by zero. */
static bool apply_binary(char op, int64_t a, int64_t b, int64_t *out)
{
    switch (op) {
    case '+':
        if ((b > 0 && a > INT64_MAX - b) || (b < 0 && a < INT64_MIN - b))
            return false;
        *out = a + b;
        return true;
    case '-':
        if ((b < 0 && a > INT64_MAX + b) || (b > 0 && a < INT64_MIN + b))
            return false;
        *out = a - b;
        return true;
    case '*':
        if (a > 0) {
            if ((b > 0 && a > INT64_MAX / b) || (b < 0 && b < INT64_MIN / a))
                return false;
        } else if (a < 0) {
            if ((b > 0 && a < INT64_MIN / b) || (b < 0 && a < INT64_MAX / b))
                return false;
        }
        *out = a * b;
        return true;
    case '/':
        if (b == 0 || (a == INT64_MIN && b == -1))
            return false;
        *out = a / b;
        return true;
    case '%':
        if (b == 0)
            return false;
        *out = b == -1 ? 0 : a % b;
        return true;
    default:
        return false;
    }
}

/* Pop the top operator and apply it to the value stack. */
static bool reduce(Evaluator *ev)
{
    char op = ev->ops[--ev->nops];

    if (op == OP_NEG) {
        if (ev->nvals < 1)
            return false;
        int64_t *v = &ev->vals[ev->nvals - 1];
        if (*v == INT64_MIN)
            return false;
        *v = -*v;
        return true;
    }
    if (op == '(' || ev->nvals < 2)
        return false;
    int64_t b = ev->vals[--ev->nvals];
    int64_t *a = &ev->vals[ev->nvals - 1];
    return apply_binary(op, *a, b, a);
}

static void evaluator_reserve(Evaluator *ev, size_t cap)
{
    if (cap <= ev->cap)
        return;
    ev->vals = xrealloc(ev->vals, cap * sizeof *ev->vals);
    ev->ops = xrealloc(ev->ops, cap);
    ev->cap = cap;
}

/* Evaluate the expression in s[0..len); false means "error". */
static bool evaluate(Evaluator *ev, const char *s, size_t len, int64_t *result)
{
    /* Every stack entry consumes at least one input character. */
    evaluator_reserve(ev, len + 1);
    ev->nvals = 0;
    ev->nops = 0;

    bool want_operand = true;
    size_t i = 0;

    while (i < len) {
        char c = s[i];

        if (is_blank(c)) {
            i++;
        } else if (want_operand) {
            if (is_digit(c)) {
                int64_t v = 0;
                for (; i < len && is_digit(s[i]); i++) {
                    int d = s[i] - '0';
                    if (v > (INT64_MAX - d) / 10)
                        return false;
                    v = v * 10 + d;
                }
                ev->vals[ev->nvals++] = v;
                want_operand = false;
            } else if (c == '-') {
                ev->ops[ev->nops++] = OP_NEG;
                i++;
            } else if (c == '(') {
                ev->ops[ev->nops++] = '(';
                i++;
            } else {
                return false;
            }
        } else if (c == '+' || c == '-' || c == '*' || c == '/' || c == '%') {
            int prec = precedence(c);
            while (ev->nops > 0 && precedence(ev->ops[ev->nops - 1]) >= prec) {
                if (!reduce(ev))
                    return false;
            }
            ev->ops[ev->nops++] = c;
            want_operand = true;
            i++;
        } else if (c == ')') {
            while (ev->nops > 0 && ev->ops[ev->nops - 1] != '(') {
                if (!reduce(ev))
                    return false;
            }
            if (ev->nops == 0)
                return false; /* unmatched ')' */
            ev->nops--;
            i++;
        } else {
            return false;
        }
    }

    if (want_operand)
        return false;
    while (ev->nops > 0) {
        if (ev->ops[ev->nops - 1] == '(' || !reduce(ev))
            return false;
    }
    if (ev->nvals != 1)
        return false;
    *result = ev->vals[0];
    return true;
}

static bool is_blank_line(const char *s, size_t len)
{
    for (size_t i = 0; i < len; i++) {
        if (!is_blank(s[i]))
            return false;
    }
    return true;
}

int cmd_calc(FILE *in, FILE *out)
{
    LineReader reader;
    line_reader_init(&reader, in);
    Evaluator ev = { 0 };

    const char *line;
    size_t len;
    while (line_reader_next(&reader, &line, &len)) {
        if (is_blank_line(line, len))
            continue;
        int64_t value;
        if (evaluate(&ev, line, len, &value))
            fprintf(out, "%" PRId64 "\n", value);
        else
            fputs("error\n", out);
    }

    free(ev.vals);
    free(ev.ops);
    line_reader_free(&reader);
    return 0;
}

#ifndef SUITE_COMMANDS_H
#define SUITE_COMMANDS_H

#include <stdio.h>

/* Each subcommand reads `in`, writes `out` and returns the exit status. */
int cmd_wordfreq(FILE *in, FILE *out);
int cmd_lru(FILE *in, FILE *out);
int cmd_calc(FILE *in, FILE *out);

#endif

/*
 * lru: an LRU cache simulator.
 *
 * Entries live in a growable node pool and are addressed by index. A
 * doubly linked list orders them from most (head) to least (tail) recently
 * used, and a chained hash table maps keys to nodes. Every command runs in
 * O(1) expected time.
 */
#include <inttypes.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#include "commands.h"
#include "util.h"

#define MAX_TOKEN 64
#define MAX_CAPACITY 1000000
#define NIL UINT32_MAX
#define INITIAL_BUCKETS ((uint32_t)1 << 10)
#define INITIAL_NODES ((uint32_t)1 << 10)

typedef struct {
    uint32_t prev;  /* towards the most recently used end */
    uint32_t next;  /* towards the least recently used end */
    uint32_t chain; /* next node in the same hash bucket, or free list link */
    uint32_t hash;
    uint8_t key_len;
    uint8_t val_len;
    char key[MAX_TOKEN];
    char val[MAX_TOKEN];
} Node;

typedef struct {
    Node *nodes;
    uint32_t nodes_cap;
    uint32_t nodes_len; /* nodes ever handed out from the pool */
    uint32_t free_head;
    uint32_t *buckets;
    uint32_t bucket_mask;
    uint32_t size;
    uint32_t capacity;
    uint32_t head;
    uint32_t tail;
} Lru;

typedef struct {
    const char *ptr;
    size_t len;
} Token;

static uint32_t hash_key(const char *key, size_t len)
{
    uint32_t h = UINT32_C(2166136261);
    for (size_t i = 0; i < len; i++)
        h = (h ^ (unsigned char)key[i]) * UINT32_C(16777619);
    return h;
}

static void lru_init(Lru *c, uint32_t capacity)
{
    c->capacity = capacity;
    c->nodes_cap = capacity < INITIAL_NODES ? capacity : INITIAL_NODES;
    c->nodes = xmalloc((size_t)c->nodes_cap * sizeof *c->nodes);
    c->nodes_len = 0;
    c->free_head = NIL;
    c->bucket_mask = INITIAL_BUCKETS - 1;
    c->buckets = xmalloc((size_t)INITIAL_BUCKETS * sizeof *c->buckets);
    for (uint32_t i = 0; i < INITIAL_BUCKETS; i++)
        c->buckets[i] = NIL;
    c->size = 0;
    c->head = c->tail = NIL;
}

static void lru_free(Lru *c)
{
    free(c->nodes);
    free(c->buckets);
}

/* ---- recency list ---- */

static void list_unlink(Lru *c, uint32_t i)
{
    Node *n = &c->nodes[i];
    if (n->prev != NIL)
        c->nodes[n->prev].next = n->next;
    else
        c->head = n->next;
    if (n->next != NIL)
        c->nodes[n->next].prev = n->prev;
    else
        c->tail = n->prev;
}

static void list_push_front(Lru *c, uint32_t i)
{
    Node *n = &c->nodes[i];
    n->prev = NIL;
    n->next = c->head;
    if (c->head != NIL)
        c->nodes[c->head].prev = i;
    else
        c->tail = i;
    c->head = i;
}

static void list_touch(Lru *c, uint32_t i)
{
    if (c->head != i) {
        list_unlink(c, i);
        list_push_front(c, i);
    }
}

/* ---- hash index ---- */

static uint32_t index_find(const Lru *c, const char *key, size_t len, uint32_t hash)
{
    for (uint32_t i = c->buckets[hash & c->bucket_mask]; i != NIL; i = c->nodes[i].chain) {
        const Node *n = &c->nodes[i];
        if (n->hash == hash && n->key_len == len && memcmp(n->key, key, len) == 0)
            return i;
    }
    return NIL;
}

static void index_insert(Lru *c, uint32_t i)
{
    uint32_t *bucket = &c->buckets[c->nodes[i].hash & c->bucket_mask];
    c->nodes[i].chain = *bucket;
    *bucket = i;
}

static void index_remove(Lru *c, uint32_t i)
{
    uint32_t *link = &c->buckets[c->nodes[i].hash & c->bucket_mask];
    while (*link != i)
        link = &c->nodes[*link].chain;
    *link = c->nodes[i].chain;
}

static void index_grow(Lru *c)
{
    uint32_t count = (c->bucket_mask + 1) * 2;
    free(c->buckets);
    c->buckets = xmalloc((size_t)count * sizeof *c->buckets);
    c->bucket_mask = count - 1;
    for (uint32_t i = 0; i < count; i++)
        c->buckets[i] = NIL;
    for (uint32_t i = c->head; i != NIL; i = c->nodes[i].next)
        index_insert(c, i);
}

/* ---- node pool ---- */

static uint32_t node_alloc(Lru *c)
{
    if (c->free_head != NIL) {
        uint32_t i = c->free_head;
        c->free_head = c->nodes[i].chain;
        return i;
    }
    if (c->nodes_len == c->nodes_cap) {
        uint32_t cap = c->nodes_cap * 2;
        if (cap > c->capacity)
            cap = c->capacity;
        c->nodes = xrealloc(c->nodes, (size_t)cap * sizeof *c->nodes);
        c->nodes_cap = cap;
    }
    return c->nodes_len++;
}

static void node_release(Lru *c, uint32_t i)
{
    c->nodes[i].chain = c->free_head;
    c->free_head = i;
}

/* Detach node `i` from the index and the list and return it to the pool. */
static void lru_remove(Lru *c, uint32_t i)
{
    index_remove(c, i);
    list_unlink(c, i);
    node_release(c, i);
    c->size--;
}

/* ---- commands ---- */

static void lru_set(Lru *c, Token key, Token val)
{
    uint32_t hash = hash_key(key.ptr, key.len);
    uint32_t i = index_find(c, key.ptr, key.len, hash);

    if (i == NIL) {
        if (c->size == c->capacity)
            lru_remove(c, c->tail);
        i = node_alloc(c);
        Node *n = &c->nodes[i];
        n->hash = hash;
        n->key_len = (uint8_t)key.len;
        memcpy(n->key, key.ptr, key.len);
        index_insert(c, i);
        list_push_front(c, i);
        if (++c->size > c->bucket_mask + 1)
            index_grow(c);
    } else {
        list_touch(c, i);
    }

    Node *n = &c->nodes[i];
    n->val_len = (uint8_t)val.len;
    memcpy(n->val, val.ptr, val.len);
}

static void lru_get(Lru *c, Token key, FILE *out)
{
    uint32_t i = key.len <= MAX_TOKEN ? index_find(c, key.ptr, key.len, hash_key(key.ptr, key.len)) : NIL;
    if (i == NIL) {
        fputs("NULL\n", out);
        return;
    }
    list_touch(c, i);
    fwrite(c->nodes[i].val, 1, c->nodes[i].val_len, out);
    fputc('\n', out);
}

static void lru_del(Lru *c, Token key, FILE *out)
{
    uint32_t i = key.len <= MAX_TOKEN ? index_find(c, key.ptr, key.len, hash_key(key.ptr, key.len)) : NIL;
    if (i != NIL)
        lru_remove(c, i);
    fputs(i != NIL ? "1\n" : "0\n", out);
}

/* ---- input parsing ---- */

/* Split `line` on spaces into at most `max` tokens; returns the token count. */
static size_t tokenize(const char *line, size_t len, Token *tokens, size_t max)
{
    size_t count = 0;
    size_t i = 0;

    while (i < len && count < max) {
        while (i < len && line[i] == ' ')
            i++;
        if (i == len)
            break;
        size_t start = i;
        while (i < len && line[i] != ' ')
            i++;
        tokens[count++] = (Token){ line + start, i - start };
    }
    return count;
}

static bool token_is(Token t, const char *word)
{
    size_t n = strlen(word);
    return t.len == n && memcmp(t.ptr, word, n) == 0;
}

static bool parse_capacity(const char *line, size_t len, uint32_t *capacity)
{
    uint64_t value = 0;
    size_t i = 0;

    while (i < len && (line[i] == ' ' || line[i] == '\t'))
        i++;
    size_t digits_start = i;
    while (i < len && line[i] >= '0' && line[i] <= '9') {
        value = value * 10 + (uint64_t)(line[i] - '0');
        if (value > MAX_CAPACITY)
            return false;
        i++;
    }
    while (i < len && (line[i] == ' ' || line[i] == '\t' || line[i] == '\r'))
        i++;
    if (i == digits_start || i != len || value < 1)
        return false;
    *capacity = (uint32_t)value;
    return true;
}

int cmd_lru(FILE *in, FILE *out)
{
    LineReader reader;
    line_reader_init(&reader, in);

    const char *line;
    size_t len;
    uint32_t capacity;

    if (!line_reader_next(&reader, &line, &len)) {
        line_reader_free(&reader);
        return 0;
    }
    if (!parse_capacity(line, len, &capacity)) {
        fputs("app: lru: invalid capacity\n", stderr);
        line_reader_free(&reader);
        return 0;
    }

    Lru cache;
    lru_init(&cache, capacity);

    while (line_reader_next(&reader, &line, &len)) {
        if (len > 0 && line[len - 1] == '\r')
            len--;

        Token tok[3];
        size_t n = tokenize(line, len, tok, 3);
        if (n == 0)
            continue;

        if (token_is(tok[0], "SET") && n >= 3) {
            if (tok[1].len <= MAX_TOKEN && tok[2].len <= MAX_TOKEN)
                lru_set(&cache, tok[1], tok[2]);
        } else if (token_is(tok[0], "GET") && n >= 2) {
            lru_get(&cache, tok[1], out);
        } else if (token_is(tok[0], "DEL") && n >= 2) {
            lru_del(&cache, tok[1], out);
        } else if (token_is(tok[0], "SIZE")) {
            fprintf(out, "%" PRIu32 "\n", cache.size);
        }
    }

    lru_free(&cache);
    line_reader_free(&reader);
    return 0;
}

#include <stdio.h>
#include <string.h>

#include "commands.h"

#define OUTPUT_BUFFER_SIZE ((size_t)1 << 16)

static const struct {
    const char *name;
    int (*run)(FILE *in, FILE *out);
} commands[] = {
    { "wordfreq", cmd_wordfreq },
    { "lru", cmd_lru },
    { "calc", cmd_calc },
};

static int usage(void)
{
    fputs("usage: app <wordfreq|lru|calc>  (reads stdin, writes stdout)\n", stderr);
    return 2;
}

int main(int argc, char **argv)
{
    if (argc != 2)
        return usage();

    for (size_t i = 0; i < sizeof commands / sizeof commands[0]; i++) {
        if (strcmp(argv[1], commands[i].name) == 0) {
            static char outbuf[OUTPUT_BUFFER_SIZE];
            setvbuf(stdout, outbuf, _IOFBF, sizeof outbuf);

            int status = commands[i].run(stdin, stdout);
            if (fflush(stdout) != 0 || ferror(stdout)) {
                perror("app: write error");
                return 1;
            }
            return status;
        }
    }
    return usage();
}

#include "util.h"

#include <stdlib.h>
#include <string.h>

#define LINE_READER_INITIAL_CAP ((size_t)64 * 1024)

noreturn void die(const char *msg)
{
    fprintf(stderr, "app: %s\n", msg);
    exit(1);
}

void *xmalloc(size_t size)
{
    void *p = malloc(size ? size : 1);
    if (!p)
        die("out of memory");
    return p;
}

void *xrealloc(void *ptr, size_t size)
{
    void *p = realloc(ptr, size ? size : 1);
    if (!p)
        die("out of memory");
    return p;
}

void *xcalloc(size_t count, size_t size)
{
    void *p = calloc(count ? count : 1, size ? size : 1);
    if (!p)
        die("out of memory");
    return p;
}

void line_reader_init(LineReader *r, FILE *fp)
{
    r->fp = fp;
    r->cap = LINE_READER_INITIAL_CAP;
    r->buf = xmalloc(r->cap);
    r->pos = 0;
    r->len = 0;
    r->eof = false;
}

void line_reader_free(LineReader *r)
{
    free(r->buf);
    r->buf = NULL;
    r->cap = r->pos = r->len = 0;
}

bool line_reader_next(LineReader *r, const char **line, size_t *len)
{
    size_t scanned = 0; /* bytes after pos already known to hold no '\n' */

    for (;;) {
        char *start = r->buf + r->pos;
        size_t avail = r->len - r->pos;
        char *nl = avail > scanned ? memchr(start + scanned, '\n', avail - scanned) : NULL;

        if (nl) {
            *line = start;
            *len = (size_t)(nl - start);
            r->pos += *len + 1;
            return true;
        }
        if (r->eof) {
            if (avail == 0)
                return false;
            *line = start;
            *len = avail;
            r->pos = r->len;
            return true;
        }
        scanned = avail;

        /* Move the partial line to the front, growing if it fills the buffer. */
        if (r->pos > 0) {
            memmove(r->buf, start, avail);
            r->pos = 0;
            r->len = avail;
        }
        if (r->len == r->cap) {
            r->cap *= 2;
            r->buf = xrealloc(r->buf, r->cap);
        }

        size_t n = fread(r->buf + r->len, 1, r->cap - r->len, r->fp);
        r->len += n;
        if (n == 0)
            r->eof = true;
    }
}

#ifndef SUITE_UTIL_H
#define SUITE_UTIL_H

#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#include <stdnoreturn.h>

/* Print "app: <msg>" to stderr and exit with status 1. */
noreturn void die(const char *msg);

/* Allocation wrappers that abort the program on failure. */
void *xmalloc(size_t size);
void *xrealloc(void *ptr, size_t size);
void *xcalloc(size_t count, size_t size);

/*
 * Buffered reader that yields one line at a time, without its terminating
 * '\n'. A final line lacking '\n' is still returned. Lines may be of any
 * length; the internal buffer grows as needed.
 */
typedef struct {
    FILE *fp;
    char *buf;
    size_t cap;
    size_t pos; /* start of unconsumed data */
    size_t len; /* end of valid data */
    bool eof;
} LineReader;

void line_reader_init(LineReader *r, FILE *fp);
void line_reader_free(LineReader *r);

/*
 * Fetch the next line. On success stores a pointer to it (valid until the
 * next call) and its length, and returns true. Returns false at end of input.
 */
bool line_reader_next(LineReader *r, const char **line, size_t *len);

#endif

/*
 * wordfreq: count case-folded runs of ASCII letters and print the ten most
 * frequent, ordered by count descending, then word ascending (byte order).
 */
#include <inttypes.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#include "commands.h"
#include "util.h"

#define TOP_N 10
#define READ_CHUNK ((size_t)1 << 16)
#define TABLE_INITIAL_SLOTS ((size_t)1 << 12)

#define FNV64_OFFSET UINT64_C(0xcbf29ce484222325)
#define FNV64_PRIME UINT64_C(0x100000001b3)

/* A slot is empty when count == 0. Word bytes live in the table's arena. */
typedef struct {
    uint64_t hash;
    size_t off;
    size_t len;
    uint64_t count;
} WordEntry;

typedef struct {
    WordEntry *slots;
    size_t mask; /* slot count - 1; slot count is a power of two */
    size_t used;
    char *arena;
    size_t arena_len;
    size_t arena_cap;
} WordTable;

static void table_init(WordTable *t)
{
    t->slots = xcalloc(TABLE_INITIAL_SLOTS, sizeof *t->slots);
    t->mask = TABLE_INITIAL_SLOTS - 1;
    t->used = 0;
    t->arena_cap = (size_t)1 << 16;
    t->arena = xmalloc(t->arena_cap);
    t->arena_len = 0;
}

static void table_free(WordTable *t)
{
    free(t->slots);
    free(t->arena);
}

static void table_grow(WordTable *t)
{
    size_t new_slots = (t->mask + 1) * 2;
    size_t new_mask = new_slots - 1;
    WordEntry *slots = xcalloc(new_slots, sizeof *slots);

    for (size_t i = 0; i <= t->mask; i++) {
        const WordEntry *e = &t->slots[i];
        if (e->count == 0)
            continue;
        size_t j = (size_t)e->hash & new_mask;
        while (slots[j].count != 0)
            j = (j + 1) & new_mask;
        slots[j] = *e;
    }
    free(t->slots);
    t->slots = slots;
    t->mask = new_mask;
}

static size_t arena_store(WordTable *t, const char *word, size_t len)
{
    if (t->arena_cap - t->arena_len < len) {
        size_t cap = t->arena_cap;
        while (cap - t->arena_len < len)
            cap *= 2;
        t->arena = xrealloc(t->arena, cap);
        t->arena_cap = cap;
    }
    size_t off = t->arena_len;
    memcpy(t->arena + off, word, len);
    t->arena_len += len;
    return off;
}

static void table_add(WordTable *t, const char *word, size_t len, uint64_t hash)
{
    size_t i = (size_t)hash & t->mask;

    for (;;) {
        WordEntry *e = &t->slots[i];
        if (e->count == 0)
            break;
        if (e->hash == hash && e->len == len && memcmp(t->arena + e->off, word, len) == 0) {
            e->count++;
            return;
        }
        i = (i + 1) & t->mask;
    }

    WordEntry *e = &t->slots[i];
    e->hash = hash;
    e->off = arena_store(t, word, len);
    e->len = len;
    e->count = 1;

    /* Keep the load factor at or below 1/2 for short probe sequences. */
    if (++t->used * 2 > t->mask + 1)
        table_grow(t);
}

/* True if `a` ranks strictly before `b` in the output order. */
static bool ranks_before(const WordTable *t, const WordEntry *a, const WordEntry *b)
{
    if (a->count != b->count)
        return a->count > b->count;
    size_t n = a->len < b->len ? a->len : b->len;
    int c = memcmp(t->arena + a->off, t->arena + b->off, n);
    if (c != 0)
        return c < 0;
    return a->len < b->len;
}

static void print_top(const WordTable *t, FILE *out)
{
    const WordEntry *top[TOP_N];
    size_t n = 0;

    for (size_t i = 0; i <= t->mask; i++) {
        const WordEntry *e = &t->slots[i];
        if (e->count == 0)
            continue;
        if (n == TOP_N && !ranks_before(t, e, top[n - 1]))
            continue;

        size_t j = n < TOP_N ? n++ : TOP_N - 1;
        while (j > 0 && ranks_before(t, e, top[j - 1])) {
            top[j] = top[j - 1];
            j--;
        }
        top[j] = e;
    }

    for (size_t i = 0; i < n; i++) {
        fprintf(out, "%" PRIu64 " ", top[i]->count);
        fwrite(t->arena + top[i]->off, 1, top[i]->len, out);
        fputc('\n', out);
    }
}

int cmd_wordfreq(FILE *in, FILE *out)
{
    /* Maps each byte to its lowercase letter, or 0 for separators. */
    unsigned char fold[256] = { 0 };
    for (int c = 'a'; c <= 'z'; c++) {
        fold[c] = (unsigned char)c;
        fold[c - 'a' + 'A'] = (unsigned char)c;
    }

    WordTable table;
    table_init(&table);

    unsigned char *chunk = xmalloc(READ_CHUNK);
    size_t word_cap = 256;
    char *word = xmalloc(word_cap);
    size_t word_len = 0;
    uint64_t hash = FNV64_OFFSET;

    size_t n;
    while ((n = fread(chunk, 1, READ_CHUNK, in)) > 0) {
        for (size_t i = 0; i < n; i++) {
            unsigned char c = fold[chunk[i]];
            if (c) {
                if (word_len == word_cap) {
                    word_cap *= 2;
                    word = xrealloc(word, word_cap);
                }
                word[word_len++] = (char)c;
                hash = (hash ^ c) * FNV64_PRIME;
            } else if (word_len) {
                table_add(&table, word, word_len, hash);
                word_len = 0;
                hash = FNV64_OFFSET;
            }
        }
    }
    if (word_len)
        table_add(&table, word, word_len, hash);

    print_top(&table, out);

    free(word);
    free(chunk);
    table_free(&table);
    return 0;
}
